-- Additive Release D remaining workflows. Generated from schema additions; apply with prisma migrate deploy.
CREATE TABLE IF NOT EXISTS "furniture_approvals" ("id" TEXT PRIMARY KEY,"business_id" TEXT NOT NULL,"custom_order_id" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'pending',"revision" INTEGER NOT NULL DEFAULT 1,"approved_by" TEXT,"notes" TEXT,"approved_at" TIMESTAMP(3),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "furniture_approvals_business_id_custom_order_id_status_idx" ON "furniture_approvals"("business_id","custom_order_id","status");
CREATE TABLE IF NOT EXISTS "furniture_warranty_claims" ("id" TEXT PRIMARY KEY,"business_id" TEXT NOT NULL,"warranty_id" TEXT NOT NULL,"claim_no" TEXT NOT NULL,"issue" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'open',"resolution" TEXT,"opened_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"closed_at" TIMESTAMP(3));
CREATE UNIQUE INDEX IF NOT EXISTS "furniture_warranty_claims_business_id_claim_no_key" ON "furniture_warranty_claims"("business_id","claim_no");
CREATE TABLE IF NOT EXISTS "workshop_part_reservations" ("id" TEXT PRIMARY KEY,"business_id" TEXT NOT NULL,"job_card_id" TEXT NOT NULL,"product_id" TEXT NOT NULL,"quantity" DECIMAL(14,3) NOT NULL,"status" TEXT NOT NULL DEFAULT 'reserved',"idempotency_key" TEXT,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS "workshop_part_reservations_business_id_idempotency_key_key" ON "workshop_part_reservations"("business_id","idempotency_key");
CREATE TABLE IF NOT EXISTS "workshop_quality_checks" ("id" TEXT PRIMARY KEY,"business_id" TEXT NOT NULL,"job_card_id" TEXT NOT NULL,"result" TEXT NOT NULL,"checklist" JSONB,"notes" TEXT,"checked_by" TEXT,"checked_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "workshop_invoices" ("id" TEXT PRIMARY KEY,"business_id" TEXT NOT NULL,"job_card_id" TEXT NOT NULL,"invoice_no" TEXT NOT NULL,"total" DECIMAL(14,2) NOT NULL,"paid_amount" DECIMAL(14,2) NOT NULL DEFAULT 0,"balance" DECIMAL(14,2) NOT NULL,"status" TEXT NOT NULL DEFAULT 'unpaid',"idempotency_key" TEXT,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS "workshop_invoices_business_id_invoice_no_key" ON "workshop_invoices"("business_id","invoice_no");
CREATE UNIQUE INDEX IF NOT EXISTS "workshop_invoices_business_id_idempotency_key_key" ON "workshop_invoices"("business_id","idempotency_key");
CREATE TABLE IF NOT EXISTS "workshop_payments" ("id" TEXT PRIMARY KEY,"business_id" TEXT NOT NULL,"invoice_id" TEXT NOT NULL,"amount" DECIMAL(14,2) NOT NULL,"method" TEXT NOT NULL DEFAULT 'cash',"reference" TEXT,"idempotency_key" TEXT,"paid_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS "workshop_payments_business_id_idempotency_key_key" ON "workshop_payments"("business_id","idempotency_key");
CREATE TABLE IF NOT EXISTS "workshop_service_reminders" ("id" TEXT PRIMARY KEY,"business_id" TEXT NOT NULL,"vehicle_id" TEXT NOT NULL,"due_at" TIMESTAMP(3) NOT NULL,"due_mileage" INTEGER,"status" TEXT NOT NULL DEFAULT 'pending',"message" TEXT);
CREATE TABLE IF NOT EXISTS "wholesale_customer_price_assignments" ("id" TEXT PRIMARY KEY,"business_id" TEXT NOT NULL,"customer_id" TEXT NOT NULL,"price_list_id" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true);
CREATE UNIQUE INDEX IF NOT EXISTS "wholesale_customer_price_assignments_business_id_customer_id_key" ON "wholesale_customer_price_assignments"("business_id","customer_id");
CREATE TABLE IF NOT EXISTS "wholesale_unit_conversions" ("id" TEXT PRIMARY KEY,"business_id" TEXT NOT NULL,"product_id" TEXT NOT NULL,"from_unit" TEXT NOT NULL,"to_unit" TEXT NOT NULL,"factor" DECIMAL(14,6) NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "wholesale_unit_conversions_business_id_product_id_from_unit_to_unit_key" ON "wholesale_unit_conversions"("business_id","product_id","from_unit","to_unit");
CREATE TABLE IF NOT EXISTS "wholesale_packing_lists" ("id" TEXT PRIMARY KEY,"business_id" TEXT NOT NULL,"packing_no" TEXT NOT NULL,"pick_list_id" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'open',"packed_by" TEXT,"packed_at" TIMESTAMP(3));
CREATE UNIQUE INDEX IF NOT EXISTS "wholesale_packing_lists_business_id_packing_no_key" ON "wholesale_packing_lists"("business_id","packing_no");
CREATE TABLE IF NOT EXISTS "wholesale_delivery_routes" ("id" TEXT PRIMARY KEY,"business_id" TEXT NOT NULL,"name" TEXT NOT NULL,"driver_name" TEXT,"vehicle_reference" TEXT,"active" BOOLEAN NOT NULL DEFAULT true);
CREATE UNIQUE INDEX IF NOT EXISTS "wholesale_delivery_routes_business_id_name_key" ON "wholesale_delivery_routes"("business_id","name");
CREATE TABLE IF NOT EXISTS "wholesale_collections" ("id" TEXT PRIMARY KEY,"business_id" TEXT NOT NULL,"sales_order_id" TEXT NOT NULL,"customer_id" TEXT NOT NULL,"amount" DECIMAL(14,2) NOT NULL,"method" TEXT NOT NULL DEFAULT 'bank',"reference" TEXT,"idempotency_key" TEXT,"collected_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS "wholesale_collections_business_id_idempotency_key_key" ON "wholesale_collections"("business_id","idempotency_key");
